<?php

declare(strict_types=1);
namespace App\Models;

use App\Core\Database;use PDO;use RuntimeException;
final class RefereeMatchAssignment
{
    public static function invite(int $matchId,int $actorUserId,int $refereeProfileId,string $message=''): int
    {
        $match=FootballMatch::findForUser($matchId,$actorUserId);if(!$match||FootballMatch::managerSide($match,$actorUserId)===null)throw new RuntimeException('Bu maç adına hakem daveti gönderme yetkin yok.');$s=Database::connection()->prepare('SELECT r.*,u.display_name FROM referee_profiles r INNER JOIN users u ON u.id=r.user_id WHERE r.id=:id AND r.status="active" AND u.status="active" LIMIT 1');$s->execute(['id'=>$refereeProfileId]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($r))throw new RuntimeException('Yayınlanmış hakem profili bulunamadı.');if((string)$r['availability_status']==='unavailable')throw new RuntimeException('Bu hakem şu anda maç teklifi kabul etmiyor.');$pdo=Database::connection();$q=$pdo->prepare('SELECT id,status FROM referee_match_assignments WHERE match_id=:match AND referee_profile_id=:ref LIMIT 1');$q->execute(['match'=>$matchId,'ref'=>$refereeProfileId]);$existing=$q->fetch(PDO::FETCH_ASSOC);if(is_array($existing)){if(in_array((string)$existing['status'],['invited','accepted'],true))return(int)$existing['id'];$u=$pdo->prepare('UPDATE referee_match_assignments SET invited_by_user_id=:actor,status="invited",message=:message,responded_at=NULL,updated_at=NOW() WHERE id=:id');$u->execute(['actor'=>$actorUserId,'message'=>self::nullEmpty($message),'id'=>(int)$existing['id']]);return(int)$existing['id'];}$i=$pdo->prepare('INSERT INTO referee_match_assignments (match_id,referee_profile_id,invited_by_user_id,status,message) VALUES (:match,:ref,:actor,"invited",:message)');$i->execute(['match'=>$matchId,'ref'=>$refereeProfileId,'actor'=>$actorUserId,'message'=>self::nullEmpty($message)]);return(int)$pdo->lastInsertId();
    }
    public static function respond(int $assignmentId,int $userId,string $decision): ?array
    {
        if(!in_array($decision,['accepted','declined'],true))return null;$status=$decision==='accepted'?'accepted':'declined';$pdo=Database::connection();$s=$pdo->prepare('SELECT a.*,r.user_id FROM referee_match_assignments a INNER JOIN referee_profiles r ON r.id=a.referee_profile_id WHERE a.id=:id AND r.user_id=:user LIMIT 1');$s->execute(['id'=>$assignmentId,'user'=>$userId]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($r)||(string)$r['status']!=='invited')return null;if($status==='accepted'){$pdo->prepare('UPDATE referee_match_assignments SET status="cancelled",responded_at=NOW(),updated_at=NOW() WHERE match_id=:match AND id<>:id AND status="accepted"')->execute(['match'=>(int)$r['match_id'],'id'=>$assignmentId]);}$u=$pdo->prepare('UPDATE referee_match_assignments SET status=:status,responded_at=NOW(),updated_at=NOW() WHERE id=:id AND status="invited"');$u->execute(['status'=>$status,'id'=>$assignmentId]);return['match_id'=>(int)$r['match_id'],'status'=>$status];
    }
    public static function forMatch(int $matchId): ?array{$s=Database::connection()->prepare('SELECT a.*,r.slug,r.classification,r.license_status,u.id user_id,u.display_name,u.profile_verified_at,p.avatar_path FROM referee_match_assignments a INNER JOIN referee_profiles r ON r.id=a.referee_profile_id INNER JOIN users u ON u.id=r.user_id LEFT JOIN player_profiles p ON p.user_id=u.id WHERE a.match_id=:match AND a.status IN ("invited","accepted","completed") ORDER BY FIELD(a.status,"accepted","completed","invited"),a.updated_at DESC LIMIT 1');$s->execute(['match'=>$matchId]);$r=$s->fetch(PDO::FETCH_ASSOC);return is_array($r)?$r:null;}
    public static function pendingForUser(int $userId): array{$s=Database::connection()->prepare('SELECT a.*,m.match_at,m.province,m.district,home.name home_team_name,away.name away_team_name FROM referee_match_assignments a INNER JOIN referee_profiles r ON r.id=a.referee_profile_id INNER JOIN matches m ON m.id=a.match_id INNER JOIN teams home ON home.id=m.home_team_id INNER JOIN teams away ON away.id=m.away_team_id WHERE r.user_id=:user AND a.status="invited" ORDER BY m.match_at ASC');$s->execute(['user'=>$userId]);return$s->fetchAll(PDO::FETCH_ASSOC)?:[];}
    private static function nullEmpty(string $v): ?string{$v=trim($v);return$v===''?null:substr($v,0,500);}
}
